fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        // Calculate the threshold index for column j: j <= i + k
        // i is usize, convert to i32 for arithmetic with k
        let threshold = (i as i32) + k;
        let mut row = Vec::with_capacity(m);
        for j in 0..m {
            // j as i32 for comparison
            if (j as i32) <= threshold {
                row.push(1.0);
            } else {
                row.push(0.0);
            }
        }
        matrix.push(row);
    }
    matrix
}